async function makeButton(type,state,label){
  const f=figma.createComponent(); f.name=`Type=${type}, State=${state}`;
  lib.appendChild(f);
  f.layoutMode='HORIZONTAL'; f.primaryAxisSizingMode='AUTO'; f.counterAxisSizingMode='AUTO';
  f.primaryAxisAlignItems='CENTER'; f.counterAxisAlignItems='CENTER';
  f.itemSpacing=10; f.paddingLeft=28; f.paddingRight=28; f.paddingTop=16; f.paddingBottom=16;
  f.cornerRadius=12; f.clipsContent=false;
  let bg=C.primary, fg=C.white, stroke=null;
  if(type==='Secondary'){bg=C.secondary;fg=C.ink;}
  if(type==='Ghost'){bg=C.white;fg=C.primary;stroke=C.primary;}
  if(type==='Outline'){bg='#FFFFFF';fg=C.ink;stroke='#E4DDD5';}
  if(state==='Hover'){bg = type==='Primary'?'#D95F19': type==='Secondary'?'#F5A000': type==='Ghost'?'#FFF1E6':'#F7F3EE'; fg = type==='Secondary'&&type!=='Primary'?C.ink:fg;}
  if(state==='Disabled'){bg= type==='Primary'?'#F6C9AE': type==='Ghost'?'#FBF6F1':'#EFEAE4'; fg= type==='Primary'?'#FFFFFF':'#B2A99F';}
  f.fills=[solid(bg)];
  if(stroke){f.strokes=[solid(stroke)];f.strokeWeight=1.5;f.strokeAlign='INSIDE';}
  if(state==='Hover'&&type==='Primary'){f.effects=[{type:'DROP_SHADOW',color:{r:0.945,g:0.447,b:0.157,a:0.28},offset:{x:0,y:6},radius:14,spread:0,visible:true,blendMode:'NORMAL'}];}
  const t=txt(f,'Label',label,0,0,200,{size:16,weight:'Bold',color:fg,lh:22});
  return f;
}
