function rgba(hex,a){const h=hex.replace('#','');const n=parseInt(h,16);return {r:((n>>16)&255)/255,g:((n>>8)&255)/255,b:(n&255)/255,a:a===undefined?1:a};}
function solid(hex,o){return {type:'SOLID',color:rgba(hex,o===undefined?1:o)};}
function frame(p,name,x,y,w,h,hex,r,clip){const n=figma.createFrame();n.name=name;n.resize(w,h);p.appendChild(n);n.x=x;n.y=y;n.fills=hex?[solid(hex)]:[];if(r)n.cornerRadius=r;if(clip!==false)n.clipsContent=true;return n;}
function txt(p,name,chars,x,y,w,o){o=o||{};const n=figma.createText();n.name=name;n.fontName={family:'Source Sans Pro',style:o.weight||'Regular'};n.fontSize=o.size||16;n.characters=chars;p.appendChild(n);n.textAutoResize='HEIGHT';n.resize(w,Math.max(1,n.height));n.x=x;n.y=y;n.fills=[solid(o.color||C.ink)];n.lineHeight={unit:'PIXELS',value:o.lh||Math.round((o.size||16)*1.45)};if(o.ls)n.letterSpacing={unit:'PIXELS',value:o.ls};if(o.align)n.textAlignHorizontal=o.align;return n;}
const cache={};async function comp(id){if(!cache[id])cache[id]=await figma.getNodeByIdAsync(id);return cache[id];}
async function inst(p,id,x,y,w,h,name){const c=await comp(id);const i=c.createInstance();p.appendChild(i);i.resize(w,h);i.x=x;i.y=y;if(name)i.name=name;return i;}
function recolor(n,hex){if(n.strokes&&n.strokes.length)n.strokes=[solid(hex)];if(n.fills&&n.fills.length&&n.fills[0].type==='SOLID')n.fills=[solid(hex)];if(n.children)for(const c of n.children)recolor(c,hex);}
async function ic(p,id,x,y,s,hex){const i=await inst(p,id,x,y,s,s);i.fills=[];recolor(i,hex);return i;}

