  f.resize(190,44); f.cornerRadius=10; f.clipsContent=true;
  f.fills=[solid(state==='Current'?'#FFFFFF':state==='Hover'?'#FAF6F1':'#F5F1EC')];
  if(state==='Current') f.effects=[{type:'DROP_SHADOW',color:rgba('#7A5230',0.10),offset:{x:0,y:2},radius:6,spread:0,visible:true,blendMode:'NORMAL'}];
  if(state==='Disabled') f.fills=[solid('#F5F1EC')];
  const ic1=await inst(f,iconId,20,12,20,20); ic1.fills=[];
  recolor(ic1, state==='Current'?C.primary: state==='Disabled'?'#C4BAB0':C.muted);
