async function mkTab(state,label,iconId){
  const f=figma.createComponent(); lib.appendChild(f);
  f.name='State='+state; f.resize(190,44); f.cornerRadius=10; f.clipsContent=true;
  let bg='#F5F1EC'; let fg=C.ink2; let w='Regular';
  if(state==='Current'){bg='#FFFFFF';fg=C.primary;w='Bold';}
  if(state==='Hover'){bg='#FAF6F1';}
  if(state==='Disabled'){bg='#F5F1EC';fg='#C4BAB0';}
  f.fills=[solid(bg)];
  if(state==='Current'){f.effects=[{type:'DROP_SHADOW',color:rgba('#7A5230',0.10),offset:{x:0,y:2},radius:6,spread:0,visible:true,blendMode:'NORMAL'}];}
  const i=await inst(f,iconId,20,12,20,20,'Icon'); i.fills=[]; recolor(i,fg);
  const t=txt(f,'Label',label,46,11,120,{size:15,weight:w,color:fg,lh:22});
  return f;
}
